function frame(t, p, d) {
  const s0 = spr(t, 0.2, 0.8, 7);
  const sL0 = E_OUT(clamp((t - 0.9) * 2));
  const s1 = spr(t, 1.4, 0.8, 7);
  const sL1 = E_OUT(clamp((t - 2.1) * 2));
  const s2 = spr(t, 2.6, 0.8, 7);

  // Step 1: Engine Card
  cards[0].style.opacity = clamp(s0 * 2);
  cards[0].style.transform = `translateY(${lerp(40, 0, s0)}px) scale(${lerp(0.9, 1, s0)})`;

  // Step 2: First Connector
  lines[0].el.style.strokeDashoffset = lines[0].len * (1 - sL0);

  // Step 3: Cold Start Card
  cards[1].style.opacity = clamp(s1 * 2);
  cards[1].style.transform = `translateY(${lerp(40, 0, s1)}px) scale(${lerp(0.9, 1, s1)})`;

  // Step 4: Second Connector
  lines[1].el.style.strokeDashoffset = lines[1].len * (1 - sL1);

  // Step 5: Runtime Card
  cards[2].style.opacity = clamp(s2 * 2);
  cards[2].style.transform = `translateY(${lerp(40, 0, s2)}px) scale(${lerp(0.9, 1, s2)})`;
}
